// Entrée : un item n8n par ligne {WEB_0, DOCOR_0, BPCNUM_0, MNT_0}
const rows = $input.all().flatMap(i =>
  Array.isArray(i.json) ? i.json : [i.json]
);

// Date au format jjmmyyyy
const now = new Date();
const jj = String(now.getDate()).padStart(2, '0');
const mm = String(now.getMonth() + 1).padStart(2, '0');
const yyyy = now.getFullYear();
const datePart = `${jj}${mm}${yyyy}`;

// Suffixe aléatoire de 4 caractères (a-z, 0-9), unique dans cette exécution
const used = new Set();
function genSuffix() {
  let s;
  do {
    s = Math.random().toString(36).slice(2, 6).padEnd(4, '0');
  } while (used.has(s));
  used.add(s);
  return s;
}

// Un identifiant DIFFÉRENT pour chaque item
return rows.map(r => ({
  json: {
    id_df: `DF-${datePart}-${genSuffix()}`,
    ...r
  }
}));

const rows = $input.all().flatMap(i =>
  Array.isArray(i.json) ? i.json : [i.json]
);

const esc = s => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;')
  .replace(/>/g, '&gt;').replace(/"/g, '&quot;');

// 2026-10-28T00:00:00.000Z -> 28/10/2026
const fmtDate = d => {
  if (!d) return '';
  const [y, m, j] = new Date(d).toISOString().slice(0, 10).split('-');
  return `${j}/${m}/${y}`;
};

// 21341.04 -> 21 341,04
const fmtMontant = n => {
  const [ent, dec] = Number(n || 0).toFixed(2).split('.');
  return `${ent.replace(/\B(?=(\d{3})+(?!\d))/g, ' ')},${dec}`;
};

return rows.map(r => {
  const datePrel = fmtDate(r.ACCDAT_0);
  const montant = fmtMontant(r.MNT_0);
  const designation = (r.designation || '').trim();

  const subject = `Demande de facture – Prélèvement du ${datePrel} – Réf. ${r.id_df}`;

  const html = `
<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#222;line-height:1.6;">
  <p>Bonjour,</p>

  <p>Nous avons constaté un prélèvement sur notre compte en date du
  <strong>${esc(datePrel)}</strong>, pour un montant de
  <strong>${esc(montant)} MAD</strong>. Sauf erreur de notre part, nous n'avons
  pas reçu la facture correspondante.</p>

  <table style="border-collapse:collapse;margin:16px 0;">
    <tr>
      <td style="padding:6px 12px;border:1px solid #ccc;background:#f5f5f5;"><strong>Date de prélèvement</strong></td>
      <td style="padding:6px 12px;border:1px solid #ccc;">${esc(datePrel)}</td>
    </tr>
    <tr>
      <td style="padding:6px 12px;border:1px solid #ccc;background:#f5f5f5;"><strong>Montant</strong></td>
      <td style="padding:6px 12px;border:1px solid #ccc;">${esc(montant)} MAD</td>
    </tr>
    <tr>
      <td style="padding:6px 12px;border:1px solid #ccc;background:#f5f5f5;"><strong>Objet</strong></td>
      <td style="padding:6px 12px;border:1px solid #ccc;">${esc(designation)}</td>
    </tr>
  </table>

  <p>Nous vous remercions de bien vouloir nous transmettre cette facture
  <strong>en répondant à cet email</strong>, en conservant la référence
  <strong>${esc(r.id_df)}</strong> dans l'objet.</p>

  <p>Cordialement,</p>
  <p>
    <strong>Service Comptabilité</strong><br>
    Briqueterie JBEL ANNOUR
  </p>
</div>`.trim();

  return {
    json: {
      ...r,
      to: r.WEB_0,
      subject,
      html,
    },
  };
});
